import { describe, it, expect } from 'vitest';
import * as git from 'isomorphic-git';
import {
  createTestContext,
  recordEvent,
  getDatabase,
  insertNode,
  type HiveContext,
  type Node,
} from '@hive/core';

const branch = 'hive-test';
async function bootstrap(): Promise<{ ctx: HiveContext; dir: string }> {
  const dir = '/test-repo';
  const ctx = await createTestContext(dir);
  ctx.fs.mkdirSync(dir, { recursive: true });
  ctx.fs.mkdirSync(`${dir}/.hive`, { recursive: true });
  await git.init({ fs: ctx.fs as any, dir, defaultBranch: 'main' });
  await git.setConfig({ fs: ctx.fs as any, dir, path: 'user.name', value: 'Test User' });
  await git.setConfig({ fs: ctx.fs as any, dir, path: 'user.email', value: 'test@example.com' });
  ctx.fs.writeFileSync(`${dir}/README.md`, '# Test');
  await git.add({ fs: ctx.fs as any, dir, filepath: 'README.md' });
  await git.commit({ fs: ctx.fs as any, dir, message: 'Initial commit',
    author: { name: 'Test User', email: 'test@example.com' } });
  await git.branch({ fs: ctx.fs as any, dir, ref: branch });
  return { ctx, dir };
}
async function addNode(ctx: HiveContext, title: string): Promise<string> {
  const id = await recordEvent(ctx, { type: 'add', nodeType: 'decision', content: title, confidence: 90 }, branch);
  const db = getDatabase(ctx);
  const now = new Date().toISOString();
  const node: Node = { change_id: id, branch, node_type: 'decision', title, status: 'pending', created_at: now, updated_at: now };
  insertNode(db, node);
  return id;
}

describe('recordEvent status writer records the value a transition came FROM', () => {
  it('populates state_transitions.old_value with the prior status on a chained transition', async () => {
    const { ctx } = await bootstrap();

    // Node exists in the db and 'decision' supports status, so recordEvent's status
    // branch (event-store.ts:118-131) writes the state_transition row directly.
    const id = await addNode(ctx, 'x');

    // First transition: pending -> active.
    await recordEvent(ctx, { type: 'status', nodeId: id, status: 'active' }, branch);

    // Second transition: active -> completed. The before/after pair the schema, the
    // StateTransition interface and the table's very name promise means this row must
    // name 'active' as the value it transitioned FROM.
    await recordEvent(ctx, { type: 'status', nodeId: id, status: 'completed' }, branch);

    const db = getDatabase(ctx);
    // SELECT * so an absent column surfaces as `undefined` through expect() rather than
    // dying with a SQL error in setup.
    const row = db
      .prepare(`SELECT * FROM state_transitions WHERE node_id = ? AND new_value = 'completed'`)
      .get(id) as { old_value?: string | null } | undefined;

    // A transition log that cannot say what it transitioned FROM cannot be audited or
    // inverted. The completed transition came from 'active'.
    expect(row?.old_value).toBe('active');
  });
});
